import{c as t,Q as s,j as a,m as o}from"./chunks/framework.DjobWxAB.js";const b=JSON.parse('{"title":"RBQ SDK (C++)","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/rbq-sdk.md","filePath":"software/rbq-sdk.md","lastUpdated":1779182288000}'),r={name:"software/rbq-sdk.md"};function d(i,e,l,n,c,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="rbq-sdk-c" tabindex="-1">RBQ SDK (C++) <a class="header-anchor" href="#rbq-sdk-c" aria-label="Permalink to &quot;RBQ SDK (C++)&quot;">​</a></h1><p>The <strong>RBQ SDK</strong> is a C++ library for building applications that communicate with the RBQ software stack over <strong>Eclipse Cyclone DDS</strong>. It wraps DDS participants, topics, and generated message types, and provides helpers for low-level control (joint references, learned policies, timing, filters, etc.).</p><h2 id="sdk-layout" tabindex="-1">SDK layout <a class="header-anchor" href="#sdk-layout" aria-label="Permalink to &quot;SDK layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Role</th></tr></thead><tbody><tr><td><strong>DDS I/O</strong></td><td><code>Publisher</code> / <code>Subscriber</code> templates (<code>rbq_sdk/dds/</code>) — CycloneDDS-CXX readers/writers on named topics.</td></tr><tr><td><strong>Messages</strong></td><td>IDL under <code>rbq_sdk/idl/</code> → C++ types (<code>rbq_msgs</code>, <code>sensor_msgs</code>, …). Includes <strong>RBQ-specific</strong> types, some <strong>ROS 2–compatible</strong> types, and <strong>Go2-compatible</strong> types included in the build.</td></tr><tr><td><strong>Control helpers</strong></td><td>e.g. <code>JointControl</code>, <code>Policy</code> / <code>PolicyParams</code> (ONNX + <code>info.json</code>), <code>Filter</code>, <code>Timer</code>, <code>Thread</code> (optional RT thread).</td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>On the development PC, this repository typically targets <strong>Ubuntu 22.04 (x86_64)</strong>.</li><li><strong>CMake</strong> ≥ 3.22, <strong>C++17</strong> compiler.</li><li><strong>Cyclone DDS</strong>: bundled under <code>rbq_sdk/3rdparty/</code>; first-time builds need the DDS bootstrap script (below).</li></ul><h2 id="build-and-install-rbq-sdk" tabindex="-1">Build and install (<code>rbq_sdk/</code>) <a class="header-anchor" href="#build-and-install-rbq-sdk" aria-label="Permalink to &quot;Build and install (`rbq_sdk/`)&quot;">​</a></h2><p>From the <strong><code>rbq_sdk</code></strong> directory in the RBQ repository:</p><ol><li><p><strong>First time only</strong> — build bundled CycloneDDS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build_dds.bash</span></span></code></pre></div></li><li><p><strong>Configure, build, install</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div></li></ol><p>The install layout includes <code>include/rbq_sdk/</code> and generated IDL headers. If CMake cannot find the package, add your install prefix to <code>CMAKE_PREFIX_PATH</code>.</p><h2 id="headers-and-namespaces" tabindex="-1">Headers and namespaces <a class="header-anchor" href="#headers-and-namespaces" aria-label="Permalink to &quot;Headers and namespaces&quot;">​</a></h2><ul><li><strong>Entry point</strong>: <code>rbq_sdk/rbq_sdk.hpp</code> when provided.</li><li><strong>DDS</strong>: <code>rbq_sdk/dds/Publisher.hpp</code>, <code>Subscriber.hpp</code></li><li><strong>Generated IDL</strong>: <code>#include &lt;rbq_sdk/idl/rbq/...&gt;</code></li></ul><p>Topic names in apps are strings (e.g. <code>rt/rbq/...</code>); see examples or driver docs for the exact list.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><strong>Low-level flow</strong>: <a href="/RBQ/manual/Guides/developer-level-0.html">Level 0 Developer Guide</a></li><li><strong>Sample application</strong>: <a href="/RBQ/software/examples/rbq_example_Level0.html">rbq_example_level_0</a></li><li><strong>ROS 2 integration</strong>: <a href="/RBQ/software/ROS2.html">ROS2</a></li></ul>',15)])])}const u=t(r,[["render",d]]);export{b as __pageData,u as default};
